architecture.h4_f:
msg = CBOR{v:1، متن، پاسخ_به، ارسال_در}
ct = AES-GCM-256-رمزگذاری (k، nonce، msg، aad=room_id)
POST /api/rooms/{id}/messages {ciphertext: hex(ct)، nonce: hex}

cryptoWire.h1_f:
pt = CBOR{v:1، متن، reply_to؟، thread_id؟، ذکر؟، send_at}
ct = AES-GCM-256-رمزگذاری (کلید_اتاق، nonce، pt، aad=hex(room_id))
سیم = CBOR{
  v: 1،
  متن رمزی: hex(ct)، // طول متغیر
  nonce: hex (12 B)،
  sender_pseudo: hex(16 B)
  sent_at: unix_ms
}

cryptoWire.h5_f:
بیرونی = CBOR{
  source_node: hex32،
  target_user: int64,
  inner_ciphertext: بایت،
  inner_nonce: بایت،
  sent_at: unix_ms
}
sig = Ed25519-Sign(source_priv, outer)
POST /فدراسیون/تحویل { پاکت: بیرونی، علامت: hex64 }

auth.h1_f:
POST /api/authentication/register
  { نام کاربری، رمز عبور، x25519_public_key، display_name، تلفن؟، ایمیل؟، avatar_emoji }

پاسخ 201 ایجاد شد:
  { access_token، refresh_token، user_id، username، ... }

auth.h3_f:
Access_token payload:
  { sub: user_id، jti: device_id، typ: "access"، expir: now + 15min }
refresh_token payload:
  { sub: user_id، jti: device_id، typ: "refresh"، expir: now + 30d }

HS256-امضا شده با راز 64 بایتی node از env.

auth.h4_f:
register_begin(): چالش = rand(32)
                    گزینه = { rp.id، user.id، pubKeyCredParams، چالش }
                    گزینه های بازگشت

register_finish (تأیید):
  تأیید گواهی در برابر TPM / Secure Enclave root CA
  ذخیره { credential_id، public_key، counter: 0 }

auth.h7_f:
POST /api/authentication/qr/begin
  → { nonce: 128-bit hex, ttl: 60 }
QR payload = { nonce, user_id, server: "https://node.example" }

POST /api/authentication/qr/verify { nonce }
  → دستگاه جدید ثبت شده؛ JWT ها بازگشتند.

rooms.h6_f:
sender_pseudo = HMAC-SHA256(room_pseudo_salt, sender_id)[:16] // 32 hex
متن رمزی = AES-GCM-رمزگذاری (روم_کلید، nonce، CBOR_payload، aad=room_id)

قاب خروجی: { type:"m", room, msg:{id, ct, nonce, sender_pseudo, sent_at} }

files.h2_f:
init POST /api/files/resumable/init {filename, size, chunk_size_hint}
            ← {upload_id، chunk_size}
قطعه PUT /api/files/resumable/{upload_id}/chunk/{offset} <ct bytes>
            ← 204
نهایی کردن POST /api/files/resumable/{upload_id}/finalise {plain_blake3}
            ← 201 {file_id, url}
TTL در ناتمام: 24 ساعت

files.h4_f:
لیست_رد = {
  "application/x-dosexec"،
  "application/x-sharedlib"،
  "application/x-mach-binary"،
}
if magic.from_buffer(buf[:1024]) در deny_list: بازگشت 415

presence.h1_f:
مشتری: در اولین فشار → ارسال {type:"t"، state:"start"}
         دیگر برای 3 ثانیه ارسال نمی شود مگر اینکه حالت تغییر کند
         10 ثانیه پس از آخرین زدن کلید → ارسال {type:"t"، وضعیت:"stop"}
گیرنده: توقف خودکار 10 ثانیه پس از آخرین "شروع" اگر "توقف" نیامد

calls.h1_f:
POST /api/calls/{room_id}/start {video, audio} → call_id
WS پخش {type:"c"، kind:"invite"، call_id}
WS پخش {نوع:"c"، نوع:"پیشنهاد"، sdp}
WS پخش {type:"c"، kind:"answer"، sdp}
WS پخش {نوع: "c"، نوع: "کاندیدا"، یخ} × N
POST /api/calls/{call_id}/end

federation.h2_f:
پاکت = {
  source_node : hex32,
  target_user : int64,
  inner_ciphertext: بایت،
  inner_nonce: بایت،
  sent_at : unix_ms,
}
sig = Ed25519Sign(source_priv، CBOR(پاکت))
POST /فدراسیون/تحویل { پاکت، علامت }

gossip.h3_f:
advertisement = {pubkey, endpoint, advertised_at}
sig = Ed25519-Sign(pubkey_priv, CBOR(تبلیغات))
محموله شایعات: [...، {ad، sig}، ...]

گیرنده: تایید sig در برابر ad.pubkey → ذخیره اگر خوب است
اضافی: PoW 2^18 صفر اول در {pubkey, endpoint}

stealth.h2_f:
ClientHello بایت = chrome_120_template با {
  تصادفی = تصادفی ما،
  server_name = نام میزبان ما (یا ECH-پیچیده شده)،
  session_id = شناسه جلسه ما،
}
JA4 = t13d_xxxx_xxxx_xxxx (با ثبات فعلی Chrome مطابقت دارد)

stealth.h4_f:
DoH: POST https://cloudflare-dns.com/dns-query {name: x.vortexx.sol}
ECH: ClientHello.extensions += encrypted_sni(public_key_from_HTTPS_record)
DGA: domain(t) = base32( SHA256(seed ∥ YYYY-MM-DD) )[:16] + ".example"

push.h4_f:
iOS NSE: didReceive(درخواست) { decrypt(request.content.userInfo) }
Android FCM: onMessageReceived(RemoteMessage) { decrypt(remoteMessage.data) }
وب SW: self.addEventListener('push', e => رمزگشایی (e.data))

controller.h2_f:
ابزار = علامت_ابزار
ورودی = درخت منبع، کلیدها/release.key
آشکار = {
  نسخه: "0.1.0"،
  ساخته شده_at: unix_ms،
  فایل ها: [{path, sha256, size}, ...]
}
sig = Ed25519-Sign(release_priv, CBOR(manifest))
خروجی = INTEGRITY.sig.json = {مانیفست، امضا شده توسط: pub_hex، علامت: sig_hex}

bots.h1_f:
ایجاد: POST /api/bots {username, display_name, code}
          → {bot_id، نشانه، pubkey}
اجرا: در فرآیند (کوروتین درون گره)
      OR خارجی (طولان‌نظرسنجی /api/bots/{id}/به‌روزرسانی‌ها، token-ath'd)
پیام: {text، امضا: Ed25519-Sign(bot_priv, canonical_msg)}

bots.h2_f:
در / شروع {
  ارسال "Welcome, {ctx.first_name}"
}
در /add <item> {
  state.list = (state.list یا []) + [ctx.args.item]
  emit "افزوده شد: {ctx.args.item}"
}

security.h4_f:
canary.txt (روزانه):
  {date, sign: Ed25519-Sign(release_priv, date)}
مشتری تأیید می کند → غایب یا نامعتبر ⇒ مشکوک به مصالحه است

اورژانس:
  admin POST /api/admin/revoke-all {reason}
  پخش گره {type:"n"، event:"compromise"، reason}
  کلاینت ها کلیدها را پاک می کنند، دوباره بوت استرپ را مجبور می کنند

debugging.h2_f:
نرخ هیستوگرام (در هر مسیر + روش):
  vortex_http_requests_total{مسیر، روش، وضعیت}
  vortex_http_request_duration_seconds_bucket{route,method,le}

گیج های وب سوکت:
  vortex_ws_connections{node}
  vortex_ws_fanout_queue_depth{room,user}

شمارنده های سفارشی:
  vortex_messages_sent_total{room_type}
  vortex_calls_started_total{ kind}

